def transform(grid):
    """Draw 3 between same-color markers aligned in a row or column."""
    from collections import Counter

    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    markers = [value for value in counts if value != background]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value in markers]
        for left, right in zip(cols, cols[1:]):
            if grid[r][left] == grid[r][right]:
                for c in range(left + 1, right):
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] in markers]
        for top, bottom in zip(rows, rows[1:]):
            if grid[top][c] == grid[bottom][c]:
                for r in range(top + 1, bottom):
                    out[r][c] = 3
    return out
